/* ------------------------------------------------------------------
   Shared scroll lock — reference-counted Lenis start/stop.
   Scripts call lock('reason') / unlock('reason'); Lenis only
   starts again when ALL reasons are released.
------------------------------------------------------------------- */
window.scrollLock = window.scrollLock || (() => {
  const reasons = new Set()

  function getLenis() {
    if (window.lenis) return window.lenis
    try { if (typeof lenis !== 'undefined' && lenis) return lenis } catch (e) {}
    return null
  }

  return {
    lock(reason) {
      reasons.add(reason)
      const l = getLenis()
      if (l) l.stop()
    },
    unlock(reason) {
      reasons.delete(reason)
      if (reasons.size === 0) {
        const l = getLenis()
        if (l) l.start()
      }
    },
    isLocked: () => reasons.size > 0,
  }
})()

/* ------------------------------------------------------------------
   Page Loader — count up + lights + number takeover + hero reveal

   Phase 0:           [data-load-cover] hides once we're at the top
                      (anchor loads hide it immediately)
   Phase 1 (t = 0):   count rolls in, lights turn yellow
   Phase 2 (t2):      takeover + hero images + bg lines
                      → scroll unlocks when this phase ends
                      → no-fluid devices: image saturation rides in
                        with the scale settle (Webflow holds the
                        desaturated start state in CSS)
   Phase 3 (tReveal): per group: stats roll in from blank
                      + text word/line reveals
------------------------------------------------------------------- */
function initPageLoader() {

  // ================================================================
  // CONFIG
  // ================================================================
  const CONFIG = {

    cover: {
      selector: '[data-load-cover]',
      fade: 0, // s — 0 = instant hide, >0 = fade out
      fadeEase: 'power1.out',
      settleFrames: 2, // frames scrollY must read 0 before hiding
      maxWait: 1.5, // s — hide anyway if the top never confirms
    },

    scroll: {
      lock: true, // stop Lenis while the loader runs
      skipLoaderOnAnchor: false, // true = anchor loads skip the loader
      pinTimeout: 8, // s — backstop that releases the Safari top-pin
    },

    count: {
      duration: 2,
      ease: 'expo.out',
      fallbackEnd: '98', // used only if data-odometer-end is missing
      fromBlank: true, // true = digits roll in from empty
    },

    lights: {
      color: '#FED60A',
      toColor: {
        duration: 0.35,
        ease: 'power2.out',
      },
      endOffset: 0.3, // last light done this many s before count lands
      out: {
        duration: 0.2,
        stagger: 0.08,
        ease: 'power1.out',
      },
    },

    hold: 0.05, // pause between count landing and takeover

    takeover: {
      duration: 1.2,
      ease: 'expo.inOut',
      yellowDelay: 0.025, // yellow trails white → yellow rim
      count: {
        duration: 1.0,
        ease: 'expo.inOut',
      },
    },

    hero: {
      image: {
        from: 1.2,
        duration: 1.6,
        ease: 'expo.inOut',
      },
      // No-fluid devices only (touch / reduced motion / no WebGL):
      // tweens the Webflow-set desaturation filter back to neutral.
      // Runs at t2 together with the scale settle.
      saturate: {
        duration: 1.6, // matched to hero.image so they land together
        ease: 'expo.inOut',
        delay: 0, // s after t2 — raise to let color trail the scale
      },
      lead: 0.4, // reveals start this many s BEFORE the takeover ends
      groupStagger: 0.15, // between [data-loader-reveal] groups
      bgLines: {
        delay: 0.2,
        duration: 1.6,
        stagger: { each: 0.06, from: 'random' },
        ease: 'power3.inOut',
      },
      stats: {
        duration: 1.2,
        stagger: 0.08,
        ease: 'expo.out',
      },
      text: {
        headingSplit: 'words', // 'words' or 'lines' for h1–h6
        duration: 0.8,
        lineStagger: 0.08,
        ease: 'expo.out',
        dynamicWait: 2, // s — max wait for dynamic text (race name)
        // to be seated before splitting
      },
    },
  }
  // ================================================================

  // ----------------------------------------------------------------
  // Load cover — must be released on EVERY exit path
  // ----------------------------------------------------------------
  const coverEl = document.querySelector(CONFIG.cover.selector)
  let coverHidden = false

  function hideCover() {
    if (coverHidden) return
    coverHidden = true
    if (!coverEl) return

    if (typeof gsap !== 'undefined' && CONFIG.cover.fade > 0) {
      gsap.to(coverEl, {
        autoAlpha: 0,
        duration: CONFIG.cover.fade,
        ease: CONFIG.cover.fadeEase,
        onComplete() { coverEl.style.display = 'none' },
      })
    } else {
      coverEl.style.display = 'none'
    }
  }

  function hideCoverWhenAtTop() {
    if (coverHidden) return
    const start = performance.now()
    let stable = 0

    const tick = () => {
      if (coverHidden) return
      const atTop = window.scrollY === 0 && window.pageYOffset === 0
      stable = atTop ? stable + 1 : 0

      if (stable >= CONFIG.cover.settleFrames) return hideCover()
      if (performance.now() - start >= CONFIG.cover.maxWait * 1000) return hideCover()
      requestAnimationFrame(tick)
    }

    requestAnimationFrame(tick)
  }

  // ----------------------------------------------------------------
  // Fluid detection + saturation helpers
  // ----------------------------------------------------------------

  // Will the hero-fluid WebGL effect run on this device?
  // Prefers the fluid script's own answer (script order permitting);
  // otherwise mirrors its exact gate.
  function fluidWillApply() {
    if (window.heroFluid && typeof window.heroFluid.willApply === 'function') {
      return window.heroFluid.willApply()
    }
    const canHover = window.matchMedia('(hover: hover) and (pointer: fine)').matches
    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches
    const isTouch = (navigator.maxTouchPoints || 0) > 0 || 'ontouchstart' in window
    if (isTouch || !canHover || reducedMotion) return false
    if (typeof THREE === 'undefined') return false
    return !!(
      document.querySelector('[data-trail="stage"]') &&
      document.querySelector('[data-trail="layer"]') &&
      document.querySelector('[data-depth-map]')
    )
  }

  // Builds the neutral counterpart of whatever filter Webflow set,
  // keeping the same function list so GSAP interpolates smoothly.
  // e.g. 'saturate(0) brightness(0.92)' → 'saturate(1) brightness(1)'
  function neutralFilter(filterStr) {
    if (!filterStr || filterStr === 'none') return 'none'
    return filterStr
      .replace(/(grayscale|invert|sepia)\(([^)]*)\)/g, '$1(0)')
      .replace(/(saturate|brightness|contrast|opacity)\(([^)]*)\)/g, '$1(1)')
      .replace(/blur\(([^)]*)\)/g, 'blur(0px)')
      .replace(/hue-rotate\(([^)]*)\)/g, 'hue-rotate(0deg)')
      .replace(/drop-shadow\(([^)]*)\)/g, 'drop-shadow(0 0 0 transparent)')
  }

  // Bail-out paths: clear the Webflow desaturation instantly so
  // no-fluid devices never get stuck in B/W
  function heroFilterFallback() {
    if (fluidWillApply()) return
    document.querySelectorAll('[data-hero-image]').forEach(el => {
      el.style.filter = 'none'
    })
  }

  // Signals that the loader is done moving the number SVGs, so
  // scroll-driven scripts (loader-numbers-scroll) may arm their
  // triggers. Fired when the takeover lands and on every early exit.
  function signalNumbersReady() {
    if (window.loaderNumbersReady) return
    window.loaderNumbersReady = true
    window.dispatchEvent(new CustomEvent('loader:numbers-ready'))
  }

  if (typeof gsap === 'undefined') {
    hideCover()
    heroFilterFallback()
    signalNumbersReady()
    window.loaderComplete = true
    return
  }

  const wrapper = document.querySelector('.loader_wrapper')
  if (!wrapper) {
    hideCover()
    heroFilterFallback()
    signalNumbersReady()
    window.loaderComplete = true
    return
  }

  function getLenis() {
    if (window.lenis) return window.lenis
    try { if (typeof lenis !== 'undefined' && lenis) return lenis } catch (e) {}
    return null
  }

  // Reload → always restart at the top so the loader is seen
  const navEntry = performance.getEntriesByType('navigation')[0]
  const isReload = navEntry ?
    navEntry.type === 'reload' :
    (performance.navigation && performance.navigation.type === 1)

  if (isReload) {
    if ('scrollRestoration' in history) history.scrollRestoration = 'manual'
    if (window.location.hash) {
      history.replaceState(null, '', window.location.pathname + window.location.search)
    }
    window.scrollTo(0, 0)
    const l = getLenis()
    if (l && typeof l.scrollTo === 'function') l.scrollTo(0, { immediate: true })
  }

  // Safari top-pin — snaps back any late async scroll restore
  let releaseTopPin = null

  function startTopPin() {
    let active = true

    const snapBack = () => {
      if (!active) return
      if (window.scrollY !== 0 || window.pageYOffset !== 0) {
        window.scrollTo(0, 0)
        const l = getLenis()
        if (l && typeof l.scrollTo === 'function') l.scrollTo(0, { immediate: true })
      }
    }

    window.addEventListener('scroll', snapBack, { passive: true })
    snapBack()

    const failsafe = setTimeout(() => {
      if (releaseTopPin) releaseTopPin()
    }, CONFIG.scroll.pinTimeout * 1000)

    releaseTopPin = () => {
      active = false
      window.removeEventListener('scroll', snapBack)
      clearTimeout(failsafe)
      releaseTopPin = null
    }
  }

  const hasAnchor = !!window.location.hash

  // Anchor load → no scroll to top happens, drop the cover now.
  // Otherwise → drop it the moment the top is confirmed.
  if (hasAnchor) hideCover()
  else hideCoverWhenAtTop()

  const countEl = wrapper.querySelector('[data-loader-count]')
  const lights = gsap.utils.toArray(wrapper.querySelectorAll('[data-loader-light]'))
  const bgWhite = wrapper.querySelector('[data-loader-bg="white"]')
  const bgYellow = wrapper.querySelector('[data-loader-bg="yellow"]')

  const heroImages = gsap.utils.toArray('[data-hero-image]')
  const bgLines = gsap.utils.toArray('.section_hero .bg_line')
  const revealGroupEls = gsap.utils.toArray('[data-loader-reveal]')

  // Saturation targets — only when the fluid won't handle the reveal.
  // Computed filters are read NOW, before anything touches them, so
  // the neutral counterpart matches the Webflow start state exactly.
  const fluidApplies = fluidWillApply()
  const heroFilterTargets = !fluidApplies ?
    heroImages
    .map(el => ({ el, to: neutralFilter(getComputedStyle(el).filter) }))
    .filter(t => t.to !== 'none') : []

  const endValue =
    (countEl && countEl.getAttribute('data-odometer-end')) ||
    CONFIG.count.fallbackEnd

  const startText = endValue.replace(/\d/g, '0')

  function jumpToEndState() {
    if (countEl) countEl.textContent = endValue
    gsap.set([bgWhite, bgYellow], { scale: 1, x: 0 })
    gsap.set(countEl, { scale: 0 })
    gsap.set(lights, { opacity: 0 })
    gsap.set(wrapper, { backgroundColor: 'transparent' })
    heroFilterTargets.forEach(({ el }) => { el.style.filter = 'none' })
  }

  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    jumpToEndState()
    hideCover()
    signalNumbersReady()
    window.loaderComplete = true
    return
  }

  if (hasAnchor && CONFIG.scroll.skipLoaderOnAnchor) {
    jumpToEndState()
    hideCover()
    signalNumbersReady()
    window.loaderComplete = true
    return
  }

  if (isReload && !hasAnchor) startTopPin()

  // Zeros reserve the correct width; element stays hidden until roll
  if (countEl) {
    countEl.textContent = startText
    gsap.set(countEl, { autoAlpha: 0 })
  }

  // Hero start states (covered by the giant numbers → flash-safe).
  // Desaturation start state comes from Webflow CSS — nothing to set.
  if (heroImages.length) gsap.set(heroImages, { scale: CONFIG.hero.image.from })
  if (bgLines.length) gsap.set(bgLines, { height: '0%' })

  // True opacity from CSS, captured BEFORE anything is hidden —
  // reveals restore THIS value, never a hardcoded 1, so elements
  // styled below 100% opacity in Webflow reveal at their true value
  function baseOpacity(node) {
    const o = parseFloat(getComputedStyle(node).opacity)
    return isNaN(o) ? 1 : o
  }

  const revealGroups = revealGroupEls.map(group => {

    // Stats: capture target, blank to zeros, hide
    const odos = gsap.utils.toArray(group.querySelectorAll('[data-odometer-element]')).map(
      el => {
        if (el.closest('[data-odometer-group]') || el.querySelector('[data-odometer-part]')) {
          console.warn(
            '[loader] Hero stat is also controlled by a data-odometer-group — remove it:',
            el
          )
        }
        const target = el.textContent.trim()
        const opacity = baseOpacity(el)
        el.textContent = target.replace(/\d/g, '0')
        gsap.set(el, { autoAlpha: 0 })
        return { el, target, opacity }
      })

    // Text: every heading/paragraph that isn't a stat
    const textEls = gsap.utils.toArray(group.querySelectorAll('h1, h2, h3, h4, h5, h6, p'))
      .filter(el =>
        !el.hasAttribute('data-odometer-element') &&
        !el.hasAttribute('data-loader-text-ignore')
      )
    const textOpacities = textEls.map(baseOpacity)
    gsap.set(textEls, { autoAlpha: 0 })

    return { group, odos, textEls, textOpacities, lines: [], splits: [] }
  })

  // All start states set in this synchronous tick → no flash when
  // the white Webflow cover is dropped
  gsap.set(wrapper, { backgroundColor: 'transparent' })

  // Dynamic text (countdown race name) must be seated BEFORE the
  // split — SplitText.revert() restores whatever was captured at
  // split time, so splitting the placeholder both kills the label's
  // reveal and snaps the text back afterwards. The countdown script
  // sets window.loaderDynamicTextReady once it has written the name;
  // we wait for it (bounded) only on pages that have the label.
  function waitForDynamicText(cb) {
    if (!document.querySelector('[data-countdown-name]')) return cb()
    if (window.loaderDynamicTextReady) return cb()
    const t0 = performance.now()
    const check = () => {
      if (window.loaderDynamicTextReady) return cb()
      if (performance.now() - t0 > CONFIG.hero.text.dynamicWait * 1000) {
        console.warn('[loader] Dynamic text never seated — splitting anyway.')
        return cb()
      }
      setTimeout(check, 50)
    }
    check()
  }

  // Split after fonts are ready so line breaks are correct
  if (typeof SplitText !== 'undefined') {
    gsap.registerPlugin(SplitText)
    document.fonts.ready.then(() => waitForDynamicText(() => {
      revealGroups.forEach(g => {
        g.textEls.forEach((el, ei) => {
          gsap.set(el, { autoAlpha: g.textOpacities[ei] })

          const isHeading = /^H[1-6]$/.test(el.tagName)
          const override = el.getAttribute('data-loader-split')
          const type = (override === 'words' || override === 'lines') ?
            override :
            (isHeading ? CONFIG.hero.text.headingSplit : 'lines')

          const split = SplitText.create(el, {
            type: type,
            mask: type,
            linesClass: 'loader-line',
            wordsClass: 'loader-word',
          })
          const parts = type === 'words' ? split.words : split.lines
          gsap.set(parts, { yPercent: 110 })
          g.splits.push(split)
          g.lines.push(...parts)
        })
      })
    }))
  } else {
    console.warn('[loader] SplitText not found — hero text will fade in instead.')
  }

  // Scroll lock — via shared manager, never on anchor loads
  const lockScroll = CONFIG.scroll.lock && !hasAnchor
  if (lockScroll) window.scrollLock.lock('loader')

  // Resolve the odometer updater — waits up to 2s for script order
  let tries = 0
  const maxTries = 40

  function resolveUpdater(cb) {
    if (typeof window.updateOdometer === 'function') {
      cb(window.updateOdometer)
      return
    }
    if (typeof initNumberOdometer === 'function') {
      window.updateOdometer = initNumberOdometer()
      cb(window.updateOdometer)
      return
    }
    tries++
    if (tries >= maxTries) {
      console.error('[loader] window.updateOdometer not found — running without counts.')
      cb(null)
      return
    }
    setTimeout(() => resolveUpdater(cb), 50)
  }

  resolveUpdater(buildAndPlay)

  // ----------------------------------------------------------------
  // Timeline
  // ----------------------------------------------------------------
  function buildAndPlay(update) {

    const master = gsap.timeline({
      defaults: { force3D: true },
      onComplete() {
        // Safety net — unlocking twice is harmless
        if (lockScroll) window.scrollLock.unlock('loader')
        if (releaseTopPin) releaseTopPin()
        hideCover()
        signalNumbersReady()
        // Explicit done-signal: the countdown ticker gates on this
        // instead of inferring loader state from computed styles
        // (which misreads a not-yet-initialized loader as finished)
        window.loaderComplete = true
      },
    })

    // -- Phase 1: count + lights ----------------------------------
    master.call(() => {
      if (!update || !countEl) return
      update(countEl, endValue, {
        duration: CONFIG.count.duration,
        ease: CONFIG.count.ease,
        grow: false,
        fromBlank: CONFIG.count.fromBlank,
      })
      gsap.set(countEl, { autoAlpha: 1 })
    }, null, 0)

    const lightsSpan = Math.max(
      CONFIG.lights.toColor.duration,
      CONFIG.count.duration - CONFIG.lights.endOffset
    )
    const colorStagger = lights.length > 1 ?
      Math.max(0, (lightsSpan - CONFIG.lights.toColor.duration) / (lights.length - 1)) :
      0

    master.to(lights, {
      backgroundColor: CONFIG.lights.color,
      duration: CONFIG.lights.toColor.duration,
      stagger: colorStagger,
      ease: CONFIG.lights.toColor.ease,
    }, 0)

    // -- Phase 2: takeover ----------------------------------------
    const t2 = CONFIG.count.duration + CONFIG.hold

    master.to(bgWhite, {
      scale: 1,
      x: 0,
      duration: CONFIG.takeover.duration,
      ease: CONFIG.takeover.ease,
    }, t2)

    master.to(bgYellow, {
      scale: 1,
      x: 0,
      duration: CONFIG.takeover.duration,
      ease: CONFIG.takeover.ease,
    }, t2 + CONFIG.takeover.yellowDelay)

    master.to(countEl, {
      scale: 0,
      duration: CONFIG.takeover.count.duration,
      ease: CONFIG.takeover.count.ease,
    }, t2)

    const lightsOut = gsap.timeline()
    lightsOut.to(lights, {
      opacity: 0,
      duration: CONFIG.lights.out.duration,
      stagger: CONFIG.lights.out.stagger,
      ease: CONFIG.lights.out.ease,
    })
    lightsOut.duration(CONFIG.takeover.duration * 0.5)
    master.add(lightsOut, t2)

    // Hero images settle together with the takeover
    if (heroImages.length) {
      master.to(heroImages, {
        scale: 1,
        duration: CONFIG.hero.image.duration,
        ease: CONFIG.hero.image.ease,
      }, t2)
    }

    // No-fluid devices: saturation rides in with the scale settle.
    // (When the fluid runs, the cursor reveal owns color — skipped.)
    heroFilterTargets.forEach(({ el, to }) => {
      master.to(el, {
        filter: to,
        duration: CONFIG.hero.saturate.duration,
        ease: CONFIG.hero.saturate.ease,
        onComplete() {
          // Inline 'none' overrides the Webflow class and removes
          // the (now-neutral) filter's GPU + stacking-context cost
          el.style.filter = 'none'
        },
      }, t2 + CONFIG.hero.saturate.delay)
    })

    if (bgLines.length) {
      master.to(bgLines, {
        height: '100%',
        duration: CONFIG.hero.bgLines.duration,
        stagger: CONFIG.hero.bgLines.stagger,
        ease: CONFIG.hero.bgLines.ease,
      }, t2 + CONFIG.hero.bgLines.delay)
    }

    // Scroll unlocks the moment the takeover lands; from here the
    // number SVGs are static → scroll scripts may arm
    master.call(() => {
      if (releaseTopPin) releaseTopPin()
      if (lockScroll) window.scrollLock.unlock('loader')
      signalNumbersReady()
    }, null, t2 + CONFIG.takeover.duration)

    // -- Phase 3: hero reveal --------------------------------------
    const tReveal = t2 + CONFIG.takeover.duration - CONFIG.hero.lead

    revealGroups.forEach((g, gi) => {
      const gt = tReveal + gi * CONFIG.hero.groupStagger

      // Stats roll in from blank
      g.odos.forEach((odo, i) => {
        master.call(() => {
          // Dynamic targets: [data-loader-target] resolves its value
          // at roll time via window.loaderTargets (gets duration in
          // ms so it can return the value true at landing)
          let target = odo.target
          const key = odo.el.getAttribute('data-loader-target')
          const provider =
            key && window.loaderTargets && window.loaderTargets[key]
          if (typeof provider === 'function') {
            const fresh = provider(CONFIG.hero.stats.duration * 1000)
            if (typeof fresh === 'string' && fresh) {
              target = fresh
              odo.el.textContent = target.replace(/\d/g, '0')
            }
          }

          // Digitless targets ('TBA' when the season is over) skip
          // the odometer: nothing to roll, and its per-character
          // static spans would pick up the colon-spacing CSS
          // padding and letterspace the word
          if (update && /\d/.test(target)) {
            update(odo.el, target, {
              duration: CONFIG.hero.stats.duration,
              ease: CONFIG.hero.stats.ease,
              grow: false,
              fromBlank: true,
            })
            gsap.set(odo.el, { autoAlpha: odo.opacity })
          } else {
            odo.el.textContent = target
            gsap.set(odo.el, { autoAlpha: odo.opacity })
          }
        }, null, gt + i * CONFIG.hero.stats.stagger)
      })

      // Text word/line reveals
      if (g.textEls.length) {
        master.call(() => {
          if (g.lines.length) {
            gsap.to(g.lines, {
              yPercent: 0,
              duration: CONFIG.hero.text.duration,
              stagger: CONFIG.hero.text.lineStagger,
              ease: CONFIG.hero.text.ease,
              onComplete() {
                g.splits.forEach(s => s.revert())
                gsap.set(g.textEls, { clearProps: 'visibility,opacity' })
                // revert() restores markup captured at split time —
                // scripts that write dynamic text (countdown label)
                // listen for this and re-assert their content
                window.dispatchEvent(new CustomEvent('loader:text-revealed'))
              },
            })
          } else {
            gsap.to(g.textEls, {
              autoAlpha: (i) => g.textOpacities[i],
              duration: 0.6,
              ease: 'power1.out',
            })
          }
        }, null, gt)
      }
    })
  }
}

initPageLoader();


